#!/usr/bin/env node
// Writes the `extras` and `cheat` commands in image/shell/ from src/extras.js and src/cheatsheet.js.
// Run after editing either list; test/assist.test.mjs fails when they differ.
import { writeFileSync } from "node:fs";
import { extras } from "../src/extras.js";
import { cheatsheet } from "../src/cheatsheet.js";

export function renderCheat() {
  const lines = cheatsheet.flatMap(([title, rows], i) => [
    ...(i ? [""] : []),
    `\${b}${title}\${r}`,
    ...rows.map(([keys, what]) => `  ${keys.padEnd(19)} ${what}`),
  ]);
  return `#!/bin/sh
# Generated by scripts/gen-shell.mjs from src/cheatsheet.js; edit that list, not this file.
# Original text; the idea comes from 0nn0/terminal-mac-cheatsheet.
b=$(printf '\\033[1m') r=$(printf '\\033[0m')
cat <<TXT
${lines.join("\n")}
TXT
`;
}

export function renderExtras() {
  const q = s => `'${s.replace(/'/g, `'\\''`)}'`;
  const row = (e, mgr) => {
    const how = e.script ? e.script : e[mgr] ? (mgr === "apk" ? `apk add ${e[mgr]}` : `sudo apt install -y ${e[mgr]}`) : "(not packaged here)";
    return `  row ${q(e.name)} ${q(e.what)} ${q(e.preinstalled ? "installed" : how)}`;
  };
  return `#!/bin/sh
# Generated by scripts/gen-shell.mjs from src/extras.js; edit that list, not this file.
# Picks from k4m4/terminals-are-sexy (CC0-1.0).
b=$(printf '\\033[1m') d=$(printf '\\033[2m') g=$(printf '\\033[32m') r=$(printf '\\033[0m')
row() { printf '%s%-24s%s %s\\n%26s%s%s%s\\n' "$b" "$1" "$r" "$2" "" "$g" "$3" "$r"; }
echo "Extras from terminals-are-sexy. Copy a green line, or press Extras in the TabShell header."
echo
if command -v apk >/dev/null; then
${extras.map(e => row(e, "apk")).join("\n")}
else
${extras.map(e => row(e, "apt")).join("\n")}
fi
echo
echo "\${d}More: https://github.com/k4m4/terminals-are-sexy\${r}"
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  writeFileSync(new URL("../image/shell/extras", import.meta.url), renderExtras(), { mode: 0o755 });
  writeFileSync(new URL("../image/shell/cheat", import.meta.url), renderCheat(), { mode: 0o755 });
  console.log("wrote image/shell/extras and image/shell/cheat");
}
